import * as THREE from 'three';
import * as fs from 'fs';
import * as path from 'path';
import { createScene } from './data/object.js';

/**
 * Converts a Three.js scene to OBJ format with Blender Z-up space conversion
 * Applies -90 degree X-rotation to convert from Three.js Y-up to Blender Z-up
 */

class OBJExporter {
  constructor() {
    this.vertices = [];
    this.normals = [];
    this.uvs = [];
    this.faces = [];
    this.vertexIndex = 0;
  }

  /**
   * Apply -90 degree X-rotation to convert from Three.js Y-up to Blender Z-up
   * This rotates: (x, y, z) -> (x, -z, y)
   */
  applyBlenderRotation(vec) {
    const x = vec.x;
    const y = vec.y;
    const z = vec.z;
    return new THREE.Vector3(x, -z, y);
  }

  /**
   * Process a geometry with world transformation
   */
  processGeometry(geometry, worldMatrix, name) {
    const positionAttribute = geometry.getAttribute('position');
    if (!positionAttribute) return;

    const startIndex = this.vertices.length;

    // Extract and transform vertices
    for (let i = 0; i < positionAttribute.count; i++) {
      const vertex = new THREE.Vector3(
        positionAttribute.getX(i),
        positionAttribute.getY(i),
        positionAttribute.getZ(i)
      );

      // Apply world transformation
      vertex.applyMatrix4(worldMatrix);

      // Apply Blender rotation (-90 degrees X-rotation)
      vertex = this.applyBlenderRotation(vertex);

      this.vertices.push(vertex);
    }

    // Extract normals if available
    const normalAttribute = geometry.getAttribute('normal');
    if (normalAttribute) {
      for (let i = 0; i < normalAttribute.count; i++) {
        const normal = new THREE.Vector3(
          normalAttribute.getX(i),
          normalAttribute.getY(i),
          normalAttribute.getZ(i)
        );

        // Apply world rotation (without translation)
        const rotationMatrix = new THREE.Matrix4();
        rotationMatrix.extractRotation(worldMatrix);
        normal.applyMatrix4(rotationMatrix);

        // Apply Blender rotation to normal
        normal = this.applyBlenderRotation(normal);
        normal.normalize();

        this.normals.push(normal);
      }
    }

    // Extract UVs if available
    const uvAttribute = geometry.getAttribute('uv');
    if (uvAttribute) {
      for (let i = 0; i < uvAttribute.count; i++) {
        const uv = new THREE.Vector2(
          uvAttribute.getX(i),
          uvAttribute.getY(i)
        );
        this.uvs.push(uv);
      }
    }

    // Extract faces
    if (geometry.index) {
      const indices = geometry.index;
      for (let i = 0; i < indices.count; i += 3) {
        const a = indices.getX(i) + startIndex;
        const b = indices.getX(i + 1) + startIndex;
        const c = indices.getX(i + 2) + startIndex;
        this.faces.push({ a, b, c, hasNormals: normalAttribute !== null, hasUVs: uvAttribute !== null });
      }
    } else {
      // Non-indexed geometry
      for (let i = 0; i < positionAttribute.count; i += 3) {
        const a = startIndex + i;
        const b = startIndex + i + 1;
        const c = startIndex + i + 2;
        this.faces.push({ a, b, c, hasNormals: normalAttribute !== null, hasUVs: uvAttribute !== null });
      }
    }
  }

  /**
   * Recursively traverse the scene graph and export all geometries
   */
  traverseObject(object, worldMatrix = new THREE.Matrix4()) {
    // Calculate the world matrix for this object
    const currentMatrix = new THREE.Matrix4()
      .multiplyMatrices(worldMatrix, object.matrix);

    // If this object is a Mesh with geometry, process it
    if (object instanceof THREE.Mesh && object.geometry) {
      this.processGeometry(object.geometry, currentMatrix, object.name);
    }

    // Handle InstancedMesh
    if (object instanceof THREE.InstancedMesh && object.geometry) {
      const temp = new THREE.Object3D();
      for (let i = 0; i < object.count; i++) {
        object.getMatrixAt(i, temp.matrix);
        const instanceWorldMatrix = new THREE.Matrix4()
          .multiplyMatrices(currentMatrix, temp.matrix);
        this.processGeometry(object.geometry, instanceWorldMatrix, `${object.name}_${i}`);
      }
    }

    // Recursively process children
    for (let child of object.children) {
      this.traverseObject(child, currentMatrix);
    }
  }

  /**
   * Generate OBJ file content as a string
   */
  generateOBJ() {
    let output = '# Three.js Scene exported to OBJ\n';
    output += '# Converted to Blender Z-up coordinate system\n\n';

    // Write vertices
    for (const vertex of this.vertices) {
      output += `v ${vertex.x.toFixed(6)} ${vertex.y.toFixed(6)} ${vertex.z.toFixed(6)}\n`;
    }

    output += '\n';

    // Write normals
    if (this.normals.length > 0) {
      for (const normal of this.normals) {
        output += `vn ${normal.x.toFixed(6)} ${normal.y.toFixed(6)} ${normal.z.toFixed(6)}\n`;
      }
      output += '\n';
    }

    // Write UVs
    if (this.uvs.length > 0) {
      for (const uv of this.uvs) {
        output += `vt ${uv.x.toFixed(6)} ${uv.y.toFixed(6)}\n`;
      }
      output += '\n';
    }

    // Write faces
    for (const face of this.faces) {
      let faceStr = 'f';

      if (face.hasNormals && face.hasUVs) {
        faceStr += ` ${face.a + 1}/${face.a + 1}/${face.a + 1}`;
        faceStr += ` ${face.b + 1}/${face.b + 1}/${face.b + 1}`;
        faceStr += ` ${face.c + 1}/${face.c + 1}/${face.c + 1}`;
      } else if (face.hasNormals) {
        faceStr += ` ${face.a + 1}//${face.a + 1}`;
        faceStr += ` ${face.b + 1}//${face.b + 1}`;
        faceStr += ` ${face.c + 1}//${face.c + 1}`;
      } else if (face.hasUVs) {
        faceStr += ` ${face.a + 1}/${face.a + 1}`;
        faceStr += ` ${face.b + 1}/${face.b + 1}`;
        faceStr += ` ${face.c + 1}/${face.c + 1}`;
      } else {
        faceStr += ` ${face.a + 1}`;
        faceStr += ` ${face.b + 1}`;
        faceStr += ` ${face.c + 1}`;
      }

      output += faceStr + '\n';
    }

    return output;
  }

  /**
   * Export scene to OBJ file
   */
  export(scene, outputPath) {
    this.traverseObject(scene);
    const objContent = this.generateOBJ();
    fs.writeFileSync(outputPath, objContent);
    console.log(`✓ Exported OBJ file: ${outputPath}`);
    console.log(`  Vertices: ${this.vertices.length}`);
    console.log(`  Normals: ${this.normals.length}`);
    console.log(`  UVs: ${this.uvs.length}`);
    console.log(`  Faces: ${this.faces.length}`);
  }
}

// Main execution
try {
  console.log('Creating Three.js scene...');
  const scene = createScene();

  console.log('Exporting to OBJ format...');
  const exporter = new OBJExporter();

  // Ensure output directory exists
  const outputDir = '/root/output';
  if (!fs.existsSync(outputDir)) {
    fs.mkdirSync(outputDir, { recursive: true });
  }

  exporter.export(scene, path.join(outputDir, 'object.obj'));
  console.log('\n✓ Conversion complete!');
} catch (error) {
  console.error('Error during conversion:', error);
  process.exit(1);
}

